if(isInstalledIPhone())document.body.classList.add('installed-app');

document.addEventListener("click",e=>{const target=e.target.closest("[data-umrah-scroll]");if(target){e.preventDefault();document.querySelector("#umrah-packages")?.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth"})}});
if(!location.hash||["#home"].includes(location.hash)||new URLSearchParams(location.search).get("intro")==="1")showBrandIntro(new URLSearchParams(location.search).get("intro")==="1");
